// ═══ COARSE-GRAINED: one lock for everything ═══
class CoarseBank {
    private final Object bankLock = new Object();
    private final Map<String, Integer> accounts = new HashMap<>();

    void transfer(String from, String to, int amount) {
        synchronized (bankLock) {  // ONE lock for ALL accounts!
            accounts.merge(from, -amount, Integer::sum);
            accounts.merge(to, amount, Integer::sum);
        }
    }
    // Simple! No deadlock (one lock)!
    // But: transfer SAV2001→CUR3001 BLOCKS transfer FD4001→SAV5001!
    // They touch DIFFERENT accounts but share the SAME lock → sequential!
    // 10K accounts, 200 threads → throughput limited by 1 lock!
}

// ═══ FINE-GRAINED: lock per account ═══
class FineBank {
    private final ConcurrentHashMap<String, ReentrantLock> accountLocks = new ConcurrentHashMap<>();

    private ReentrantLock getLock(String accountId) {
        return accountLocks.computeIfAbsent(accountId, k -> new ReentrantLock());
    }

    void transfer(String from, String to, int amount) {
        // LOCK ORDERING: always lock lower ID first!
        String first = from.compareTo(to) < 0 ? from : to;
        String second = first.equals(from) ? to : from;

        getLock(first).lock();
        try {
            getLock(second).lock();
            try {
                // Only THESE TWO accounts locked!
                // Other transfers on OTHER accounts: PARALLEL!
                debit(from, amount);
                credit(to, amount);
            } finally { getLock(second).unlock(); }
        } finally { getLock(first).unlock(); }
    }
    // High concurrency! Transfer A→B doesn't block C→D!
    // Lock ordering: alphabetical → no circular wait → no deadlock!
}

// ═══ PERFORMANCE COMPARISON ═══
// 10K accounts, 200 threads, 50K transfers/sec:
// Coarse: 1 lock → ~2K transfers/sec (bottleneck!)
// Fine:   10K locks → ~45K transfers/sec (22x faster!)
// Fine + ordering: same speed, zero deadlocks!
