package com.bank.granularity;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class LockGranularityTest {

    // ═══ COARSE: one lock → sequential ═══
    @Test
    void coarse_sequential() throws InterruptedException {
        Object bankLock = new Object();
        int[] accounts = new int[100];
        for (int i = 0; i < 100; i++) accounts[i] = 10000;

        long start = System.currentTimeMillis();
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < 1000; i++) {
                    synchronized (bankLock) {  // ALL transfers through ONE lock!
                        int from = ThreadLocalRandom.current().nextInt(100);
                        int to = ThreadLocalRandom.current().nextInt(100);
                        if (from != to && accounts[from] >= 100) {
                            accounts[from] -= 100;
                            accounts[to] += 100;
                        }
                    }
                }
                latch.countDown();
            }).start();
        }
        latch.await();
        long coarseTime = System.currentTimeMillis() - start;
        System.out.println("Coarse: " + coarseTime + "ms");
    }

    // ═══ FINE: lock per account → parallel! ═══
    @Test
    void fine_parallel_withOrdering() throws InterruptedException {
        ReentrantLock[] locks = new ReentrantLock[100];
        int[] accounts = new int[100];
        for (int i = 0; i < 100; i++) { locks[i] = new ReentrantLock(); accounts[i] = 10000; }

        long start = System.currentTimeMillis();
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < 1000; i++) {
                    int from = ThreadLocalRandom.current().nextInt(100);
                    int to = ThreadLocalRandom.current().nextInt(100);
                    if (from == to) continue;

                    // LOCK ORDERING: lower index first!
                    int first = Math.min(from, to);
                    int second = Math.max(from, to);

                    locks[first].lock();
                    try {
                        locks[second].lock();
                        try {
                            if (accounts[from] >= 100) {
                                accounts[from] -= 100;
                                accounts[to] += 100;
                            }
                        } finally { locks[second].unlock(); }
                    } finally { locks[first].unlock(); }
                }
                latch.countDown();
            }).start();
        }
        latch.await();
        long fineTime = System.currentTimeMillis() - start;

        // Verify money conservation:
        int total = 0;
        for (int a : accounts) total += a;
        assertThat(total).isEqualTo(100 * 10000);  // money conserved!

        System.out.println("Fine-grained: " + fineTime + "ms");
        // Fine should be FASTER than coarse!
    }

    // ═══ Fine without ordering → potential deadlock (with timeout detection) ═══
    @Test
    void fine_withoutOrdering_deadlockRisk() throws InterruptedException {
        ReentrantLock lockA = new ReentrantLock();
        ReentrantLock lockB = new ReentrantLock();
        AtomicBoolean deadlockDetected = new AtomicBoolean(false);

        Thread t1 = new Thread(() -> {
            lockA.lock();
            try { Thread.sleep(50); } catch (InterruptedException e) {}
            if (!lockB.tryLock(500, java.util.concurrent.TimeUnit.MILLISECONDS)) {
                deadlockDetected.set(true);
            } else { lockB.unlock(); }
            lockA.unlock();
        });

        Thread t2 = new Thread(() -> {
            lockB.lock();
            try { Thread.sleep(50); } catch (InterruptedException e) {}
            if (!lockA.tryLock(500, java.util.concurrent.TimeUnit.MILLISECONDS)) {
                deadlockDetected.set(true);
            } else { lockA.unlock(); }
            lockB.unlock();
        });

        t1.start(); t2.start();
        t1.join(5000); t2.join(5000);
        // Without ordering: deadlock likely! tryLock timeout detects it.
    }
}
